<script setup lang="ts">
import type { AdminGuideFormValues } from '~/composables/useAdminGuides'
definePageMeta({ middleware: 'admin-auth' })
const navigationOpen = ref(false); const saving = ref(false); const saveError = ref(''); const { getSources, createAdminGuide } = useAdminGuides(); const { data: sources, error } = await useAsyncData('admin-guide-sources', getSources)
const initialValues: AdminGuideFormValues = { slug: '', guideType: 'general', sourceId: '', status: 'draft', featured: false, lastVerifiedAt: '', title: '', summary: '', bodyMarkdown: '', coverAltText: '', coverCreditText: '' }
const save = async ({ values, coverFile, viewAfterSave }: { values: AdminGuideFormValues; coverFile: File | null; viewAfterSave: boolean }) => { saving.value = true; saveError.value = ''; try { const result = await createAdminGuide(values, coverFile); if (result.partial) { await navigateTo({ path: `/admin/guides/${result.id}`, query: { notice: 'partial-save' } }); return }; if (viewAfterSave && values.status === 'published') { await navigateTo(`/guides/${values.slug}`); return }; await navigateTo(`/admin/guides/${result.id}`) } catch (failure: unknown) { saveError.value = getAdminGuideSaveError(failure, values.slug) } finally { saving.value = false } }
</script>
<template><div class="min-h-screen bg-slate-50 lg:pl-60"><AdminSidebar :open="navigationOpen" @close="navigationOpen = false" /><AdminHeader title="Add guide" description="Create a practical travel guide as a draft or publish it when ready." @menu="navigationOpen = true" /><main class="mx-auto max-w-5xl p-4 sm:p-6 lg:p-8"><p v-if="error" class="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">Guide sources are unavailable right now.</p><template v-else-if="sources"><p v-if="saveError" class="mb-6 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">{{ saveError }}</p><AdminGuideForm :initial-values="initialValues" :sources="sources" :cover="null" :saving="saving" @save="save" /></template></main></div></template>
